import { Link, useLocation, useNavigate } from "react-router-dom";
import { API } from "../api/api";

export default function Navbar() {
  const location = useLocation();
  const nav = useNavigate();

  return (
    <nav style={styles.navbar}>
      
      <h2 style={styles.logo} onClick={() => nav("/home")}>
        PollHub 🚀
      </h2>

      <div style={styles.links}>
        <Link to="/home" style={styles.link}>
          <span style={location.pathname === "/home" ? styles.active : null}>
            Home
          </span>
        </Link>

        <Link to="/CreatPoll" style={styles.link}>
          <span style={location.pathname === "/create-poll" ? styles.active : null}>
            Create Poll
          </span>
        </Link>

        <Link to="/create-survey" style={styles.link}>
          <span style={location.pathname === "/create-survey" ? styles.active : null}>
            Create Survey
          </span>
        </Link>
      </div>

      <div style={{ display: "flex", gap: "10px" }}>
        <button
          style={styles.profile}
          onClick={async () => {
            try {
              const res = await API.get("/auth/verify");
              alert(`👤 ${res.data.user.name}\n📧 ${res.data.user.email}`);
            } catch {
              alert("Not logged in");
            }
          }}
        >
          👤
        </button>

        <button
          style={styles.logout}
          onClick={async () => {
            await API.post("/auth/logout");
            nav("/");
          }}
        >
          Logout
        </button>
      </div>
    </nav>
  );
}

const styles = {
  navbar: {
    display: "flex",
    justifyContent: "space-between",
    padding: "15px",
    background: "#111827",
    color: "white"
  },

  logo: {
    cursor: "pointer"
  },

  links: {
    display: "flex",
    gap: "20px"
  },

  link: {
    color: "#cbd5e1",
    textDecoration: "none"
  },

  active: {
    color: "#3b82f6"
  },

  profile: {
    padding: "6px 10px",
    background: "#1f2937",
    border: "none",
    color: "white",
    cursor: "pointer"
  },

  logout: {
    background: "#ef4444",
    border: "none",
    color: "white",
    padding: "6px 10px",
    cursor: "pointer"
  }
};
